def _combined(self) -> IntervalSide:
    import numpy as np

    # Handle ExtensionArray and numpy arrays by converting to numpy
    def to_numpy_array(values):
        if hasattr(values, "to_numpy"):
            return values.to_numpy()
        return np.asarray(values)

    left = to_numpy_array(self.left._values).reshape(-1, 1)
    right = to_numpy_array(self.right._values).reshape(-1, 1)

    # GH#38353 instead of casting to object, operating on a
    # complex128 ndarray is much more performant.
    if needs_i8_conversion(left.dtype):
        # Use numpy's concatenate instead
        comb = np.concatenate([left, right], axis=1)
        comb = comb.view("complex128")[:, 0]
    else:
        # Handle infinities explicitly to avoid incorrect combinations
        left_real = np.array(left.ravel(), dtype="complex128")
        right_imag = np.array(right.ravel(), dtype="complex128")

        # Only create complex numbers for finite values
        comb = np.where(np.isfinite(left_real) & np.isfinite(right_imag),
                        left_real + 1j * right_imag,
                        np.nan)

    return comb
